'use strict';
const $=s=>document.querySelector(s);
const paths={
 notes:'<path d="M9 4h24v32H9z" fill="#fff6be"/><path d="M9 4h24v7H9z" fill="#8a5a32"/><path d="M13 17h16M13 22h16M13 27h12" stroke="#b8a574" stroke-width="1.5"/>',
 projects:'<path d="M3 12h15l4 4h17v21H3z" fill="#d7ab6b"/><path d="M3 18h36l-3 19H6z" fill="#f8d094"/><path d="M9 24h21M9 29h15" stroke="#bc8a46" stroke-width="1.5"/>',
 videos:'<rect x="4" y="7" width="34" height="28" rx="4" fill="#fff"/><path d="m17 14 13 7-13 8z" fill="#d0493e"/>',
 sports:'<path d="M13 5h16v13c0 13-16 13-16 0z" fill="#ffdc70"/><path d="M13 9H6c0 10 3 14 10 14M29 9h7c0 10-3 14-10 14" fill="none" stroke="#ffe395" stroke-width="3"/><path d="M21 27v7M13 37h16" stroke="#ffe395" stroke-width="4"/>',
 photos:'<g fill="#fff3b0">'+[0,45,90,135,180,225,270,315].map(a=>`<ellipse cx="21" cy="12" rx="5" ry="11" transform="rotate(${a} 21 21)"/>`).join('')+'</g><circle cx="21" cy="21" r="7" fill="#a06624"/>',
 resume:'<path d="M9 3h17l8 8v28H9z" fill="#fafafa"/><path d="M26 3v9h8" fill="#b8d8e9"/><path d="M14 18h15M14 23h15M14 28h15M14 33h10" stroke="#6f9cb4" stroke-width="2"/>',
 contact:'<rect x="6" y="3" width="29" height="36" rx="3" fill="#dac6a6"/><circle cx="20" cy="15" r="6" fill="#8f7861"/><path d="M10 33c0-15 21-15 21 0" fill="#8f7861"/><path d="M36 10h3M36 19h3M36 28h3" stroke="#fff1db" stroke-width="3"/>',
 settings:'<path d="M17 3h8l2 6 6 1 5 7-4 5 2 6-6 6-6-2-5 5-7-3-1-6-6-3 1-8 6-2z" fill="#ddd" stroke="#fff"/><circle cx="21" cy="20" r="8" fill="#56636a" stroke="#a6b0b5" stroke-width="3"/>',
 mail:'<rect x="3" y="9" width="36" height="25" rx="3" fill="white"/><path d="m4 10 17 14L38 10M4 33l12-12M38 33 26 21" fill="none" stroke="#8bb8de" stroke-width="1.5"/>',
 linkedin:'<text x="7" y="32" fill="white" font-family="Arial" font-size="33" font-weight="bold">in</text>',
 github:'<path d="M10 13 9 5l9 4h7l8-4-1 9c9 14-1 22-10 22S1 27 10 13" fill="white"/><path d="M17 33v8M26 33v8M16 36C5 40 8 29 3 31" fill="none" stroke="white" stroke-width="3"/>',
 x:'<path d="M9 7h7l17 28h-7zM33 7 9 35" fill="none" stroke="white" stroke-width="3"/>'};
const svg=k=>`<svg viewBox="0 0 42 42" aria-hidden="true">${paths[k]}</svg>`;
const appDefs=[['notes','About me','#edce65','#c59a36'],['projects','Projects','#d5a46d','#88552b'],['videos','Videos','#f17465','#b92d2b'],['sports','Sports','#6cbd82','#277344'],['photos','Photos','#8cd4dd','#3592b8'],['resume','Résumé','#8cc6f0','#346eae'],['contact','Contact','#cbb396','#8d735b'],['settings','Settings','#aeb6be','#46535e']];
const socials=[['mail','Email','mailto:gauravbihanigb@gmail.com','#6cb9fa','#2472c8'],['linkedin','LinkedIn','https://www.linkedin.com/in/gauravbihanii','#55b0e0','#06629b'],['github','GitHub','https://github.com/gau-rav0','#767c8b','#292d3b'],['x','X','https://x.com/gauravbihanii','#50565c','#15191d']];
$('#apps').innerHTML=appDefs.map(([id,label,a,b])=>`<button class="app-icon" data-open="${id}" aria-label="Open ${label}"><span class="icon-face" style="--top:${a};--bottom:${b}">${svg(id)}</span><span>${label}</span></button>`).join('');
$('#dock').innerHTML=socials.map(([id,label,url,a,b])=>`<a class="app-icon" href="${url}" ${id==='mail'?'':'target="_blank" rel="noopener noreferrer"'} aria-label="${label}${id==='mail'?'':' (opens in a new tab)'}"><span class="icon-face" style="--top:${a};--bottom:${b}">${svg(id)}</span><span>${label}</span></a>`).join('');
const ext=(url,label)=>`<a class="app-link" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const photos=[['portrait','NIT Surat, class of 2026'],['mountains','A little perspective'],['football','Time on the field'],['basketball','Under the floodlights'],['river','Away from the screen'],['beach','A slower moment'],['lookout','Worth the climb'],['doorway','Somewhere along the way']];
const pages={
notes:()=>`<p class="kicker">A note to whoever’s visiting</p><h3>Hey, I’m Gaurav.</h3><img class="portrait-cover" src="assets/portrait.webp" alt="Gaurav at SVNIT"><p>I’m from Surat. I graduated from NIT Surat with an Integrated M.Sc. in Chemistry in 2026, and have spent the last year moving into tech.</p><p>I like the stretch between an idea and something you can actually use. That has meant building a product, exploring AI content workflows, and learning when an idea needs a rethink.</p><p>I’m interested in product, AI and growth, and want to work close to the action at a startup—taking ownership and learning through real problems.</p><p>Off-screen, you’ll find another side of me in team sports, the gym, and these photos.</p><p><em>Building. Learning. Trying again.</em></p><button class="quick-open" data-open="contact">Let’s talk →</button>`,
projects:()=>`<p class="kicker">Things I’ve put into the world</p><h3>Build. Learn. Repeat.</h3><article class="paper-card"><span class="tag">BUILT · NO TRACTION</span><h4>Follow Verified Investors</h4><p>An investor-discovery demo for exploring portfolios, comparing profiles and replaying changes.</p><p>Built the product with Next.js, TypeScript and Supabase, including database workflows and creator verification flows.</p><p><strong>The lesson:</strong> shipping a product didn’t establish demand. It didn’t find market fit or gain usage.</p><p class="notice">Investor profiles and holdings in the demo are fictional. This is a product experiment.</p>${ext('https://github.com/gau-rav0/stock-copy-autopilot','Repository')}${ext('https://fvi-ochre.vercel.app','Demo')}</article><article class="paper-card"><span class="tag">UNFINISHED EXPERIMENT</span><h4>AthleteOS</h4><p>Could I make my Samsung watch data more useful, with a WHOOP-inspired personal athlete experience?</p><p>The repo includes Android / Health Connect ingestion, a durable sync queue, Supabase and a dashboard preview.</p><p><strong>Where it stands:</strong> device validation and reliability acceptance remain incomplete. The full recovery/coaching vision wasn’t achieved.</p>${ext('https://github.com/gau-rav0/athleteos','Repository')}</article><article class="paper-card"><span class="tag">TEAM PROJECT · ANALYTICS</span><h4>MSME credit risk analysis</h4><div class="stat">1,700+</div><p class="stat-label">MSMEs in the analysis</p><p>Contributed to credit-risk and loan-eligibility analysis using Python, SQL, Power BI and Claude, including reporting for risk indicators.</p><p class="notice">Team contribution described in my résumé.</p></article>`,
videos:()=>`<p class="kicker">Content × AI workflows</p><h3>From idea to video.</h3><article class="paper-card"><h4>A little introduction</h4><video controls playsinline preload="none" poster="assets/intro-poster.jpg" aria-label="Gaurav introduction video"><source src="assets/intro.mp4" type="video/mp4">Your browser does not support video. ${ext('https://drive.google.com/file/d/1dvfXZOz6abEV7an19eMnM3XHdhzDsQsZ/view','Watch introduction')}</video><p class="notice">An introduction made with Claude.</p></article><article class="paper-card"><span class="tag">FREELANCE AI CONTENT PRODUCTION</span><h4>Litmus by Lapaas / Sahil Khanna</h4><div class="stat">50K+</div><p class="stat-label">Views reported on a video I contributed to</p><p>Contributed across research, scriptwriting, video generation and stitching.</p><p>Used transcripts and documents in Claude workflows for script creation, and Higgsfield MCP through Codex for video generation.</p><p><strong>The workflow</strong><br>Research → Script → Generate → Stitch → Publish</p>${ext('https://www.youtube.com/@litmusbylapaas','Litmus by Lapaas')}${ext('https://www.youtube.com/@IntellectualIndies','Sahil Khanna')}</article>`,
sports:()=>`<p class="kicker">There’s a team behind every win</p><h3>Beyond the screen.</h3><img class="sports-img" src="assets/basketball.webp" alt="Basketball on an outdoor court at night"><article class="paper-card"><span class="tag">2024–2026 · AIINIT SPORTS MEET</span><h4>Basketball</h4><p><strong>Vice Captain & Team Lead, SVNIT</strong></p><p>A different setting for the same habits: communicate, trust your teammates and take responsibility for your part.</p></article><article class="paper-card"><span class="tag">2025 · AIINIT SPORTS MEET</span><h4>Powerlifting</h4><p><strong>Team Lead, SVNIT</strong></p><p>Consistency in individual work. Responsibility as part of a team.</p></article><img class="sports-img" src="assets/football.webp" loading="lazy" alt="An afternoon playing football"><article class="paper-card"><span class="tag">SPARSH 2024</span><h4>Sponsorship & coordination</h4><p>As Sponsorship Head, supported outreach and coordination for campus sports events, contributing to partnerships with Red Bull and Decathlon.</p></article><article class="paper-card"><h4>Leadership off the court</h4><p>At PREGRAD, led a four-member team and owned Surat chapter logistics across 10+ events: people, schedules and on-ground execution.</p></article>`,
photos:()=>`<p class="kicker">Camera roll / a few favourites</p><h3>Life, in between.</h3><div class="photo-grid">${photos.map(([id,label])=>`<button data-photo="${id}" aria-label="View photo: ${label}"><img src="assets/${id}.webp" alt="${label}" loading="lazy"><span>${label}</span></button>`).join('')}</div>`,
resume:()=>`<p class="kicker">The one-page version</p><h3>Gaurav Bihani</h3><article class="paper-card"><p>Integrated M.Sc. in Chemistry<br>SVNIT, Surat · 2021–2026</p><p>Projects, AI content production, analytics, operations and sports leadership.</p><a class="quick-open" href="assets/gaurav-bihani-resume.pdf" download="Gaurav_Bihani_Resume.pdf">Download résumé ↓</a><p style="margin-top:14px">${ext('assets/gaurav-bihani-resume.pdf','Open PDF')}</p></article><object class="resume-preview" data="assets/gaurav-bihani-resume.pdf" type="application/pdf"><p>PDF preview unavailable. Use Open PDF above.</p></object>`,
contact:()=>`<p class="kicker">Good conversations welcome</p><h3>Let’s build something.</h3><img class="portrait-cover" src="assets/portrait.webp" alt="Gaurav at SVNIT"><article class="paper-card"><p>Open to startup roles across product, AI workflows, growth and operations.</p><div class="contact-row"><a href="mailto:gauravbihanigb@gmail.com">gauravbihanigb@gmail.com</a><button class="copy-button" id="copy-email">Copy</button></div><div class="contact-row"><span>LinkedIn</span>${ext('https://www.linkedin.com/in/gauravbihanii','gauravbihanii')}</div><div class="contact-row"><span>GitHub</span>${ext('https://github.com/gau-rav0','gau-rav0')}</div><div class="contact-row"><span>X</span>${ext('https://x.com/gauravbihanii','@gauravbihanii')}</div></article><button class="quick-open quick-view">View the quick version ↗</button>`,
settings:()=>`<p class="kicker">Make yourself at home</p><h3>A tiny bit of control.</h3><article class="paper-card"><h4>Wallpaper</h4><div class="setting-options">${wallpaperIds.map(id=>`<button class="wallpaper-option" data-wallpaper="${id}" aria-pressed="${wallpaper===id}"><img src="${wallpaperUrl(id)}" alt=""><span>${wallpaperNames[id]}</span></button>`).join('')}</div><h4>Auto-change wallpaper</h4><button class="setting-btn" id="auto-wallpaper" aria-pressed="${autoWallpaper}">${autoWallpaper?'On · every 20 seconds':'Off'}</button><p class="notice">Always starts with Classic iPhone on a fresh visit. Your photos rotate after unlocking. Choosing a wallpaper pauses rotation.</p><h4>Animations</h4><button class="setting-btn" id="motion-toggle" aria-pressed="${motion}">${motion?'On':'Off'}</button><p class="notice" style="margin-top:12px">Animation and rotation preferences stay in this browser. The starting wallpaper always resets.</p></article><article class="paper-card"><button class="quick-open" id="relock">Lock this iPhone ▣</button></article><article class="paper-card"><h4>Prefer a simple page?</h4><p>All the essentials, in one place.</p><button class="quick-open quick-view">Open quick version ↗</button></article>`};
const wallpaperIds=['classic','beach','mountains','river'];
const wallpaperNames={classic:'Classic iPhone',beach:'Beach',mountains:'Mountains',river:'River'};
let wallpaper='classic',autoWallpaper=true,rotationTimer=null,wallpaperRequest=0;
let motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
let locked=true;
try{const saved=localStorage.getItem('gb-motion');if(saved!==null)motion=saved==='true';autoWallpaper=localStorage.getItem('gb-auto-wallpaper')!=='false'}catch{}
function wallpaperUrl(id){return `assets/${id}.${id==='classic'?'svg':'webp'}`}
function setWallpaper(id){
 wallpaper=id;const request=++wallpaperRequest;const image=new Image();
 image.onload=()=>{if(request!==wallpaperRequest)return;const front=$('#wallpaper-next');front.style.backgroundImage=`url('${wallpaperUrl(id)}')`;front.classList.add('visible');
 setTimeout(()=>{if(request!==wallpaperRequest)return;$('#wallpaper-current').style.backgroundImage=front.style.backgroundImage;front.classList.remove('visible')},motion?650:0)};
 image.src=wallpaperUrl(id);
}
function startRotation(){clearInterval(rotationTimer);if(!autoWallpaper||locked)return;rotationTimer=setInterval(()=>{if(document.hidden||locked)return;setWallpaper(wallpaperIds[(wallpaperIds.indexOf(wallpaper)+1)%wallpaperIds.length]);if(location.hash==='#settings')updateWallpaperControls()},20000)}
function updateWallpaperControls(){document.querySelectorAll('[data-wallpaper]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.wallpaper===wallpaper)))}
function preferences(){document.body.classList.toggle('no-motion',!motion);try{localStorage.setItem('gb-motion',motion);localStorage.setItem('gb-auto-wallpaper',autoWallpaper)}catch{}startRotation()}
$('#wallpaper-current').style.backgroundImage=`url('${wallpaperUrl('classic')}')`;
preferences();
function syncLock(){ $('#lock-screen').hidden=!locked;$('#screen').classList.toggle('is-locked',locked);$('#home').inert=locked||Object.hasOwn(pages,location.hash.slice(1));$('#app-panel').inert=locked;$('#lock-phone').disabled=locked;startRotation()}
function unlock(){if(!locked)return;locked=false;$('#screen').classList.add('just-unlocked');syncLock();render();setTimeout(()=>$('#screen').classList.remove('just-unlocked'),650);if(!Object.hasOwn(pages,location.hash.slice(1)))$('#apps button').focus({preventScroll:true})}
function lockPhone(){locked=true;clearInterval(rotationTimer);$('#unlock-slider').value='0';$('#unlock-slider').setAttribute('aria-valuetext','Locked. Slide right, or press End to unlock.');syncLock();$('#unlock-slider').focus({preventScroll:true});document.querySelector('video')?.pause()}
$('#unlock-slider').addEventListener('input',e=>{const value=Number(e.target.value);e.target.setAttribute('aria-valuetext',value>=92?'Unlocked':`Slide to unlock: ${value}%`);if(value>=92)unlock()});
$('#unlock-slider').addEventListener('change',e=>{e.target.value='0'});
$('#skip-lock').onclick=()=>{unlock();openApp('projects')};
$('#lock-phone').onclick=lockPhone;
let returnFocus=null;
function render(){const id=location.hash.slice(1);const valid=Object.hasOwn(pages,id);$('#app-panel').hidden=!valid;$('#home').inert=valid||locked;if(valid){$('#app-title').textContent=appDefs.find(a=>a[0]===id)[1];$('#app-content').className='app-content'+(id==='notes'?' notes-page':'');$('#app-content').innerHTML=pages[id]();$('#app-content').scrollTop=0;$('#back').focus({preventScroll:true})}else if(returnFocus){returnFocus.focus({preventScroll:true});returnFocus=null}}
function openApp(id){if(locked)unlock();returnFocus=document.activeElement;if(location.hash==='#'+id)render();else location.hash=id}
function home(){if(location.hash!=='#home')location.hash='home'}
window.addEventListener('hashchange',()=>render());render();$('#back').onclick=home;$('#home-button').onclick=()=>{if(locked)$('#unlock-slider').focus({preventScroll:true});else home()};if(Object.hasOwn(pages,location.hash.slice(1)))locked=false;syncLock();
function quick(){ $('#quick-content').innerHTML=`<p class="kicker">THE QUICK VERSION</p><h2 class="quick-title">Gaurav Bihani.</h2><p>NIT Surat graduate · Surat, India<br><strong>Products · AI · Growth</strong></p><p>I build products, explore AI workflows and learn through real problems. Open to startup opportunities.</p><h3>Selected work</h3><p><strong>Litmus by Lapaas / Sahil Khanna:</strong> research, scripts, AI video generation and stitching. Reported 50K+ views on a contributed video.</p><p><strong>FVI:</strong> investor-discovery demo built with Next.js and Supabase. Didn’t find market fit or gain usage. ${ext('https://github.com/gau-rav0/stock-copy-autopilot','Code')}</p><p><strong>AthleteOS:</strong> an unfinished Samsung health-data experiment. Android ingestion, sync and a dashboard preview. ${ext('https://github.com/gau-rav0/athleteos','Code')}</p><p><strong>MSME analytics:</strong> team contribution to risk analysis across 1,700+ MSMEs using Python, SQL and Power BI.</p><h3>Teams & leadership</h3><p>SVNIT basketball Vice Captain & Team Lead, powerlifting Team Lead, SPARSH Sponsorship Head, and PREGRAD Management Head leading a four-member team across 10+ events.</p><div class="quick-links"><a href="mailto:gauravbihanigb@gmail.com">Email me ↗</a><a href="assets/gaurav-bihani-resume.pdf" download>Download résumé ↓</a><a href="https://www.linkedin.com/in/gauravbihanii" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a></div>`;$('#quick-dialog').showModal()}
$('.close-dialog').onclick=()=>$('#quick-dialog').close();$('#quick-dialog').addEventListener('click',e=>{if(e.target===$('#quick-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
document.addEventListener('click',async e=>{const o=e.target.closest('[data-open]');if(o){openApp(o.dataset.open);return}if(e.target.closest('.quick-view')){quick();return}const ph=e.target.closest('[data-photo]');if(ph){showPhoto(photos.findIndex(p=>p[0]===ph.dataset.photo));return}if(e.target.closest('[data-photo-back]')){render();return}const wp=e.target.closest('[data-wallpaper]');if(wp){autoWallpaper=false;setWallpaper(wp.dataset.wallpaper);preferences();render();return}if(e.target.closest('#motion-toggle')){motion=!motion;preferences();render();return}if(e.target.closest('#auto-wallpaper')){autoWallpaper=!autoWallpaper;preferences();render();return}if(e.target.closest('#relock')){lockPhone();return}const prev=e.target.closest('[data-photo-step]');if(prev){showPhoto((photoIndex+Number(prev.dataset.photoStep)+photos.length)%photos.length);return}const copy=e.target.closest('#copy-email');if(copy){try{await navigator.clipboard.writeText('gauravbihanigb@gmail.com');copy.textContent='Copied!';copy.setAttribute('aria-live','polite')}catch{copy.textContent='Select email';}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#quick-dialog').open)home()});
let photoIndex=0;
function showPhoto(index){photoIndex=index;const [id,label]=photos[index];$('#app-content').innerHTML=`<div class="photo-detail"><button data-photo-back>‹ Camera roll</button><img src="assets/${id}.webp" alt="${label}" draggable="false"><p>${label}</p><div class="photo-controls"><button data-photo-step="-1" aria-label="Previous photo">←</button><span>${index+1} / ${photos.length}</span><button data-photo-step="1" aria-label="Next photo">→</button></div><p class="notice">Swipe sideways to browse.</p></div>`;let x,y;const image=$('.photo-detail img');image.onpointerdown=e=>{x=e.clientX;y=e.clientY};image.onpointerup=e=>{if(x===undefined)return;const dx=e.clientX-x,dy=e.clientY-y;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.5)showPhoto((index+(dx<0?1:-1)+photos.length)%photos.length);x=undefined};}
function clock(){ $('#clock').textContent=new Intl.DateTimeFormat('en',{hour:'numeric',minute:'2-digit',hour12:false}).format(new Date());$('#lock-time').textContent=new Intl.DateTimeFormat('en',{hour:'numeric',minute:'2-digit',hour12:false}).format(new Date());$('#lock-date').textContent=new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}clock();setInterval(clock,30000);
